public:struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,1>CodeRanges{{{0x1838,0x1970}}};bool active()const{return active_||dsp_.active();}void reset(){task_=T{};active_=false;dsp_.reset();steps_=0;}uint64_t steps()const{return steps_;}static bool candidate(unsigned at){return at>=0x1838&&at<0x1970;}
